<?php $pageTitle='Platform Settings';require_once __DIR__.'/../includes/header.php';requirePlatformAdmin();$db=getDB();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();foreach(['google_site_verification','support_email','public_site_url'] as $key){$value=trim($_POST[$key]??'');$q=$db->prepare("INSERT INTO platform_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW()");$q->execute([$key,$value]);}$message='Platform settings saved.';}$settings=[];try{foreach($db->query('SELECT setting_key,setting_value FROM platform_settings') as $row)$settings[$row['setting_key']]=$row['setting_value'];}catch(Throwable $e){} ?><main class="pt-20 min-h-screen"><div class="max-w-3xl mx-auto p-4 lg:p-6"><h1 class="text-2xl font-bold">Platform Settings</h1><p class="text-slate-400 text-sm mt-1">Configure global publishing and search-verification values after your domain is ready.</p><?php if($message): ?><div class="mt-5 p-3 rounded bg-green-500/15 text-green-300"><?=$message?></div><?php endif; ?><form method="post" class="card mt-5 space-y-5"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><label><span class="label">Public site URL</span><input class="input" name="public_site_url" value="<?=sanitize($settings['public_site_url']??siteUrl('/'))?>" placeholder="https://cuepos.com"></label><label><span class="label">Google site verification token</span><input class="input" name="google_site_verification" value="<?=sanitize($settings['google_site_verification']??'')?>" placeholder="Paste only the verification token from Search Console"></label><label><span class="label">Support email</span><input class="input" type="email" name="support_email" value="<?=sanitize($settings['support_email']??'')?>" placeholder="support@cuepos.com"></label><button class="btn-primary">Save Platform Settings</button></form></div><?php require __DIR__.'/../includes/footer.php'; ?>
